def esc(s):
    return html.escape(str(s), quote=True)

def icon(name="arrow", cls="icon"):
    paths = {
        "arrow": '<path d="M5 12h14M13 6l6 6-6 6"/>',
        "external": '<path d="M8 5h11v11M19 5 5 19"/>',
        "download": '<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
        "server": '<rect x="3" y="3" width="18" height="7" rx="2"/><rect x="3" y="14" width="18" height="7" rx="2"/><path d="M7 6.5h.01M7 17.5h.01M12 6.5h5M12 17.5h5"/>',
        "key": '<circle cx="8" cy="9" r="5"/><path d="m12 13 8 8m-4-4 3-3m-7-1 3-3"/>',
        "shield": '<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',
        "people": '<circle cx="9" cy="7" r="4"/><path d="M2 21v-4a7 7 0 0 1 14 0v4M17 3a4 4 0 0 1 0 8m2 3a6 6 0 0 1 3 5v2"/>',
        "book": '<path d="M12 5v16M12 5C8 2 4 3 2 4v15c4-2 7-1 10 2 3-3 6-4 10-2V4c-3-2-7-1-10 1Z"/>',
        "copy": '<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',
        "code": '<path d="m8 5-6 7 6 7m8-14 6 7-6 7m-3-16-2 18"/>',
        "check": '<path d="m4 12 5 5L20 6"/>',
    }
    return f'<svg class="{cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{paths[name]}</svg>'

def button(label, href, kind="primary", ico="arrow", extra=""):
    return f'<a class="button {kind}" href="{href}" {extra}>{label}{icon(ico)}</a>'

def copy(text, label="Copy"):
    return f'<button class="copy-button" type="button" data-copy="{esc(text)}" aria-label="{esc(label)}">{icon("copy")}<span>Copy</span></button>'

def eyebrow(text):
    return f'<p class="eyebrow"><span class="red-dot" aria-hidden="true"></span>{text}</p>'

def header(active):
    nav = [("Start", "/start/"), ("How it works", "/architecture/"), ("Routes", "/routes/"), ("Open source", "/open-source/"), ("Rook’s worlds", "/worlds/")]
    links = ''.join(f'<a href="{url}"'+(' aria-current="page"' if active == url else '')+f'>{label}</a>' for label, url in nav)
    return f'''<a class="skip-link" href="#main">Skip to content</a>
    <header class="site-header"><div class="header-inner">
    <a class="wordmark" href="/" aria-label="Rookstride home"><img src="/assets/rook.svg" width="38" height="38" alt="">rookstride<span class="wordmark-dot">.</span></a>
    <button class="menu-toggle" aria-expanded="false" aria-controls="site-nav" type="button"><span>Menu</span><span class="menu-lines" aria-hidden="true"></span></button>
    <nav class="site-nav" id="site-nav" aria-label="Main navigation">{links}{button('Get the app', '/download/', 'nav-download', 'download')}</nav>
    </div></header>'''

