def page_head(label, title, desc, trail="", cls=""):
    return f'<section class="page-heading {cls}"><div class="container">{trail}{eyebrow(label)}<h1>{title}</h1><p class="lede">{desc}</p></div></section>'

def trail(label, parent=None):
    middle = f'<a href="{parent[1]}">{parent[0]}</a><span aria-hidden="true">/</span>' if parent else ''
    return f'<nav class="breadcrumb" aria-label="Breadcrumb"><a href="/">Home</a><span aria-hidden="true">/</span>{middle}<span aria-current="page">{label}</span></nav>'

def faq(items):
    return '<div class="faq-list">' + ''.join(f'<details><summary>{q}<span aria-hidden="true">+</span></summary><div>{a}</div></details>' for q,a in items) + '</div>'

HOME_FAQ = [
    ("Is this a VPN subscription?", "<p>No. Rookstride is a free, open-source Android app for your own VPS. You choose and pay your hosting provider. The app deploys and manages the gateway over SSH; there is no Rookstride cloud account.</p>"),
    ("Can I keep using the strongSwan app?", "<p>Yes. The administrator can connect inside Rookstride. Invited Android users can import the password-free, certificate-pinned profile into the official strongSwan app and enter their VPN password separately.</p>"),
    ("Will it remove every ad, including YouTube ads?", "<p>AdGuard Home filters DNS for separate advertising and tracking domains. It cannot reliably remove YouTube in-video ads or ads served from the same domain as the content. Apps using their own encrypted DNS may bypass filtering.</p>"),
    ("What do I need to install it?", "<p>Android 8 or later, a reachable fresh Ubuntu 24.04 VPS with a public IPv4 address, and administrator SSH access (root or passwordless sudo). The phone needs a network connection; the VPS downloads packages.</p>"),
    ("Is the current release ready for everyday reliance?", "<p>It is an early alpha. Earlier signed releases passed documented single-server and two-provider reset-and-reinstall cycles. The current app adds persistent installation progress and offline stories with a separate UI test report. Physical-device, network-handoff and sustained-load gates remain. <a href='/download/#tested'>Read the exact test scope.</a></p>"),
]

